const order = (a, b) => (b.open_to_work === 'Yes') - (a.open_to_work === 'Yes') || yrs(b) - yrs(a) || String(a.first_seen).localeCompare(String(b.first_seen));
const lists = TABS.map(([node, tab]) => {
  let rows = []; try { rows = $(node).all().map(i => i.json).filter(r => r.linkedin_url && !notFound(r)); } catch (e) { rows = []; }
  let pick;
  if (emailRun) {
    // email ke laayak: (a) Discovered + Exact, open to work ya 3+ saal  (b) Enriched (profile-only) jinka email abhi dhoondha nahi, open to work ya 2+ saal
    const fresh = rows.filter(r => r.readiness === 'Discovered' && r.title_match === 'Exact' && (r.open_to_work === 'Yes' || yrs(r) >= 3));
    // sirf woh jo PROFILE-ONLY run se enrich hue ('no email)' note). Purane runs me email pehle hi dhoondha ja chuka hai -> dobara paisa nahi
    const noEmail = rows.filter(r => r.readiness === 'Enriched' && !String(r.email || '').includes('@') && /no email\)/i.test(r.notes || '') && !/email searched/i.test(r.notes || '') && (r.open_to_work === 'Yes' || yrs(r) >= 2));
    const rest = rows.filter(r => r.readiness === 'Discovered' && r.title_match === 'Exact');
    pick = [...noEmail.sort(order), ...fresh.sort(order), ...rest.sort(order)];
  } else {
    // profile-only: pehle Exact, phir Related (title thoda alag, par pool ke shabd headline me the)
    pick = [...rows.filter(r => r.readiness === 'Discovered' && r.title_match === 'Exact').sort(order),
            ...rows.filter(r => r.readiness === 'Discovered' && r.title_match === 'Related').sort(order)];
  }
  const seen = new Set();
  return pick.filter(r => !seen.has(r.linkedin_url) && seen.add(r.linkedin_url)).map(r => ({ tab, row: r }));
});
const picks = [];
while (picks.length < LIMIT && lists.some(l => l.length))
  for (const l of lists) if (l.length && picks.length < LIMIT) picks.push(l.shift());
if (!picks.length) return [];
const mode = emailRun ? 'Profile details + email search ($10 per 1k)' : 'Profile details no email ($4 per 1k)';
const maxCharge = Math.round(picks.length * (emailRun ? 0.01 : 0.004) * 1.2 * 100) / 100 + 0.05;   // Apify isse zyada charge nahi kar sakta
