  if (!email && em) {
    email = em.email;
    const local = em.email.split('@')[0].toLowerCase(), fn = String(r.name || '').split(' ')[0].toLowerCase();
    const guess = local.length <= 12 && !/[._-]/.test(local) && (local === fn || String(r.name || '').toLowerCase().split(' ').includes(local));
    emailStatus = (em.status === 'valid' ? `Valid (score ${em.qualityScore ?? '-'})` : em.status === 'risky' || em.catchAllDomain ? `Risky (catch-all, score ${em.qualityScore ?? '-'})` : 'Invalid')
      + (guess ? ' - check: may be a pattern guess' : '');
    if (em.status === 'valid') emailsValid++; else emailsRisky++;
  }
  const edu = (p.education || []).slice(0, 2).map(e => [e.degree, e.fieldOfStudy, e.schoolName, e.period].filter(Boolean).join(', ')).join(' | ');
  const notesOld = String(r.notes || '').replace(place && place[0] ? /;?\s*Location guessed from search \([^)]*\)/ : /$^/, '').replace(/^;\s*/, '');
  const titleNow = cur.position || r.current_title;
  // pool check: abhi ka title/headline pool ka ho, ya kam se kam 1 saal pool ka kaam kiya ho. Recruiter/sales wale bahar
  const roleNow = `${titleNow || ''} ${p.headline || ''}`;
  const recruiter = P.reject.test(roleNow) && !P.rx.test(String(titleNow || ''));
  const fits = !recruiter && (P.rx.test(roleNow) || (domain !== '' && domain >= 1));
  const row = { linkedin_url: r.linkedin_url, last_updated: today };
  if (!fits) {
    rejected++;
    Object.assign(row, { readiness: 'Rejected', notes: `${notesOld}; Rejected ${today}: ${recruiter ? 'recruiter / sales role' : `profile is not ${P.label} work`}`.replace(/^; /, '') });
  } else {
    Object.assign(row, {
      headline: p.headline || r.headline,
      ...(place ? { country: place[2], ...(place[0] ? { city: place[0], state: place[1] } : {}) } : {}), current_title: titleNow, current_company: cur.companyName || r.current_company,
      total_experience_years: total, [P.domainKey]: domain,
      experience_bucket: bucket, [P.modKey]: mods.join('; '), certifications: certs.join('; '),
      skills: skills.slice(0, 12).join('; '), open_to_work: p.openToWork ? 'Yes' : 'No',
      seniority: /\bintern\b/i.test(titleNow) ? 'Intern' : /\b(head|director|manager)\b/i.test(titleNow) ? 'Manager' : /\b(lead|principal|staff|architect)\b/i.test(titleNow) ? 'Lead'
        : total !== '' && total >= 5 ? 'Senior' : total !== '' && total < 2 ? 'Junior' : 'Mid',
      past_employers: exp.filter(e => e !== cur).slice(0, 5).map(e => `${e.companyName || ''} (${e.startDate?.year || ''}-${e.endDate?.year || ''})`).join('; '),
      ...(emailRun ? { email, email_status: emailStatus, contact_source: r.contact_source || (email ? 'Apify LinkedIn profile scraper' : '') } : {}),
      readiness: 'Enriched', notes: [notesOld.replace(/;?\s*Edu: [^;]*/, '').replace(/;?\s*Full profile scraped [^;]*/, '').replace(/^;\s*/, ''), edu && `Edu: ${edu}`, `Full profile scraped ${today} (n8n${emailRun ? ', email searched' : ', no email'})`, emailRun && `Email searched ${today}`].filter(Boolean).join('; '),
