const stats = { stamp, requested: picks.length, enriched: out.filter(o => o.json.readiness === 'Enriched').length, rejected, emailsValid, emailsRisky, phones, failed: picks.length - found.size, nameMismatch, apifyDown, emailRun };
if (!out.length) return [{ json: { _tab: 'none', _stats: stats } }];
return out.map((o, i) => (i === 0 ? { json: { ...o.json, _stats: stats } } : o));

